"""API-Definition EduKSX-AI. Eigene Unterhaltungen unter /api/v1/me/…, Verwaltung, Assistenten und Wissen unter /api/v1/org/…"""

M, O = "/api/v1/me", "/api/v1/org"


def R(tabelle, schema, op, op_mehrzahl, einzahl, mehrzahl, basis, **kw):
    return {"tabelle": tabelle, "schema": schema, "op": op, "op_mehrzahl": op_mehrzahl, "einzahl": einzahl, "mehrzahl": mehrzahl,
            "pfad": f"{basis}/{kw.pop('pfad', tabelle.replace('_', '-'))}", **kw}


SCHUTZ = "enum:public=öffentlich;internal=intern;confidential=vertraulich;sensitive=besonders schützenswert"
FREIGABE = "enum:private=nur ich;groups=ausgewählte Gruppen;organization=ganze Organisation"

API = {
    "titel": "EduKSX-AI",
    "beschreibung": "Interne KI-Plattform: Chat mit offenen Modellen auf dem internen KI-Server oder bei freigegebenen Schweizer Anbietern "
                    "(OpenAI-kompatible Schnittstelle), Weiterleitung nach Schutzbedarf, Assistenten, Wissenssammlungen mit Quellen, "
                    "Werkzeuge über das Model Context Protocol, Rollen, Gruppen und Metadaten-Protokoll ohne Inhalte.",
    "tags": {
        "conversations": "Unterhaltungen", "messages": "Nachrichten und Antworten", "assistants": "Assistenten", "knowledge": "Wissenssammlungen",
        "models": "Modelle", "endpoints": "Betriebsorte", "tools": "Werkzeuge", "roles": "Rollen und Rechte", "groups": "Gruppen",
        "settings": "Organisation und Datenschutz", "status": "Systemzustand",
    },
    "ressourcen": [
        R("conversations", "Conversation", "MyConversation", "MyConversations", "Unterhaltung", "Unterhaltungen", M, filter=["is_pinned", "q"], artikel="eine",
          nur_lesen=["user_id", "last_activity_at"],
          eingebettet={"knowledge_collection_ids": ("list:uuid", "Wissen", "gewählte Sammlungen")},
          berechnet={"endpoint": ("ref:EndpointSummary?", "Betriebsort", "zulässiger Ort für Modell und Schutzbedarf; leer = keiner")},
          loeschtext="Unterhaltung mit allen Nachrichten und Anhängen endgültig löschen."),
        R("assistants", "Assistant", "Assistant", "Assistants", "Assistent", "Assistenten", O, filter=["owner_id", "q"], artikel="einen", nur_lesen=["owner_id"],
          eingebettet={"knowledge_collection_ids": ("list:uuid", "Wissen", "Sammlungen"), "group_ids": ("list:uuid", "Gruppen", "bei Freigabe «ausgewählte Gruppen»")},
          berechnet={"is_favorite": ("bool", "Favorit", "für mich markiert")}, loeschtext="Für alle löschen; bestehende Unterhaltungen bleiben."),
        R("knowledge_collections", "KnowledgeCollection", "KnowledgeCollection", "KnowledgeCollections", "Wissenssammlung", "Wissenssammlungen", O, filter=["protection_level", "q"],
          nur_lesen=["owner_id"], eingebettet={"group_ids": ("list:uuid", "Gruppen", "bei Freigabe «ausgewählte Gruppen»")},
          berechnet={"file_count": ("int", "Dateien", "Anzahl"), "chunk_count": ("int", "Abschnitte", "im Suchindex")}, loeschtext="Sammlung und Suchindex löschen."),
        R("models", "Model", "Model", "Models", "Modell", "Modelle", O, filter=["purpose", "is_enabled"], recht="admin", artikel="ein",
          eingebettet={"capabilities": ("list:text", "Fähigkeiten", "z. B. «reasoning», «vision»"), "endpoint_ids": ("list:uuid", "Läuft auf", "Betriebsorte")},
          berechnet={"allowed_levels": ("list:text", "Zulässig für", "Schutzbedarfsstufen mit zulässigem Betriebsort")}),
        R("inference_endpoints", "InferenceEndpoint", "InferenceEndpoint", "InferenceEndpoints", "Betriebsort", "Betriebsorte", O, filter=["endpoint_kind", "approval_status"], recht="admin",
          nur_lesen=["approved_by_id"], berechnet={"last_check": ("ref:EndpointCheck?", "Letzte Prüfung", "Systemzustand")}, pfad="endpoints"),
        R("tools", "Tool", "Tool", "Tools", "Werkzeug", "Werkzeuge", O, filter=["tool_kind"], recht="admin", artikel="ein"),
        R("roles", "Role", "Role", "Roles", "Rolle", "Rollen", O, recht="admin", artikel="eine", nur_lesen=["is_fixed"],
          eingebettet={"permissions": ("list:text", "Rechte", "z. B. «chat», «choose_model»")}, loeschtext="Nur ohne zugeordnete Personen; Administration nie."),
        R("user_groups", "UserGroup", "Group", "Groups", "Gruppe", "Gruppen", O, recht="admin", artikel="eine", nur_lesen=["source"],
          eingebettet={"member_ids": ("list:uuid", "Mitglieder", "Personen")}, pfad="groups", loeschtext="Gruppe aus allen Freigaben entfernen."),
        R("user_accounts", "UserAccount", "UserAccount", "UserAccounts", "Konto", "Konten", O, filter=["role_id", "is_blocked"], ops="lru", recht="admin",
          nur_lesen=["user_id", "last_active_at"], berechnet={"display_name": ("text", "Name", "aus EduKSX-Ident"), "email": ("email", "E-Mail", "Anmeldename")}),
    ],
    "schemas": {
        "EndpointSummary": {"title": "Betriebsort (kurz)", "description": "wo die Antwort entsteht",
                            "felder": {"id": ("uuid", "ID", "Betriebsort"), "name": ("text", "Name", "Anzeige"), "endpoint_kind": ("enum:internal=interner Server;ch_api=CH-Cloud Inferenz-API;ch_gpu=CH-Cloud eigene GPU;foreign=ausserhalb der Schweiz", "Art", "Betriebsmodell"),
                                       "location": ("text?", "Standort", "Rechenzentren")}},
        "Message": {"title": "Nachricht", "description": "Frage oder Antwort",
                    "felder": {"id": ("uuid", "ID", "UUID v7"), "position": ("int", "Reihenfolge", "in der Unterhaltung"), "author_role": ("enum:user=Person;assistant=Modell", "Von", "wer schreibt"),
                               "content": ("text", "Inhalt", "Markdown"), "model_id": ("uuid?", "Modell", "bei Antworten"), "inference_endpoint_id": ("uuid?", "Betriebsort", "bei Antworten"),
                               "tools_used": ("list:text", "Werkzeuge", "genutzt"), "sources": ("list:ref:Source", "Quellen", "aus Wissenssammlungen"),
                               "attachments": ("list:ref:Attachment", "Anhänge", "Dateien"), "input_tokens": ("int?", "Tokens Eingabe", "Verbrauch"), "output_tokens": ("int?", "Tokens Antwort", "Verbrauch"),
                               "duration_ms": ("int?", "Dauer (ms)", "bis vollständig"), "feedback": ("enum:helpful=hilfreich;not_helpful=nicht hilfreich?", "Rückmeldung", "Daumen"),
                               "created_at": ("datetime", "Zeitpunkt", "erstellt")}},
        "Source": {"title": "Quelle", "description": "Abschnitt aus einer Wissenssammlung",
                   "felder": {"position": ("int", "Nummer", "[n] im Text"), "knowledge_collection_id": ("uuid?", "Sammlung", "Verweis"), "file_name": ("text", "Datei", "Name"), "location_label": ("text?", "Stelle", "z. B. «Abschnitt 2»")}},
        "Attachment": {"title": "Anhang", "description": "Datei einer Nachricht",
                       "felder": {"id": ("uuid", "ID", "Anhang"), "file_name": ("text", "Datei", "Name"), "mime_type": ("text", "MIME-Typ", "Dateityp"), "size_bytes": ("int", "Grösse", "Bytes")}},
        "SendMessage": {"title": "Nachricht senden", "description": "Frage stellen; Antwort als Ereignisstrom (text/event-stream) oder vollständig",
                        "felder": {"content": ("text", "Inhalt", "Frage (Markdown)"), "attachment_ids": ("list:uuid", "Anhänge", "vorher hochgeladen"),
                                   "web_search": ("bool", "Websuche", "nur bei Schutzbedarf «öffentlich»"), "stream": ("bool", "Fortlaufend", "Antwort als Ereignisstrom"),
                                   "confirm_personal_data": ("bool", "Trotz Hinweis senden", "Personendaten-Hinweis bestätigt")}, "pflicht": ["content"]},
        "PersonalDataHint": {"title": "Personendaten-Hinweis", "description": "Antwort 409, wenn die Prüfung anschlägt und der Schutzbedarf zu tief ist",
                             "felder": {"findings": ("list:text", "Gefunden", "z. B. «AHV-Nummer»"), "required_level": (SCHUTZ, "Nötiger Schutzbedarf", "mindestens")}},
        "Feedback": {"title": "Rückmeldung", "description": "Bewertung einer Antwort",
                     "felder": {"feedback": ("enum:helpful=hilfreich;not_helpful=nicht hilfreich", "Rückmeldung", "Daumen"),
                                "feedback_reason": ("enum:wrong=inhaltlich falsch;incomplete=unvollständig;tone=Ton oder Stil;sources=Quellen;other=anderes?", "Grund", "bei «nicht hilfreich»"),
                                "feedback_comment": ("text?", "Bemerkung", "freiwillig, ohne Personendaten")}, "pflicht": ["feedback"]},
        "KnowledgeFile": {"title": "Datei", "description": "Datei einer Wissenssammlung",
                          "felder": {"id": ("uuid", "ID", "Datei"), "file_name": ("text", "Datei", "Name"), "size_bytes": ("int", "Grösse", "Bytes"),
                                     "index_status": ("enum:pending=wartet;indexing=wird indexiert;indexed=indexiert;no_text=ohne Text;failed=Fehler", "Status", "Suchindex"),
                                     "chunk_count": ("int", "Abschnitte", "im Suchindex"), "indexed_at": ("datetime?", "Indexiert am", "Zeitpunkt")}},
        "DefaultModels": {"title": "Standardmodelle", "description": "Standardmodell je Schutzbedarf",
                          "felder": {"public": ("uuid", "Öffentlich", "Modell"), "internal": ("uuid", "Intern", "Modell"), "confidential": ("uuid", "Vertraulich", "Modell"), "sensitive": ("uuid", "Besonders schützenswert", "Modell")},
                          "pflicht": ["public", "internal", "confidential", "sensitive"]},
        "Settings": {"title": "Einstellungen", "description": "Organisation und Datenschutzregeln",
                     "felder": {"display_name": ("text", "Name der Organisation", "in Briefen"), "postal_address": ("text?", "Postadresse", "in Briefen"), "phone": ("text?", "Telefon", "Sekretariat"),
                                "email": ("email?", "E-Mail", "Sekretariat"), "website": ("url?", "Website", "in Antworten"), "model_instructions": ("text?", "Hinweis an das Modell", "höchstens 1000 Zeichen"),
                                "retention_days": ("int", "Aufbewahrung (Tage)", "1–365"), "default_protection_level": (SCHUTZ, "Schutzbedarf neuer Unterhaltungen", "Vorgabe"),
                                "usage_logging": ("enum:metadata=nur Metadaten;off=aus", "Protokollierung", "nie Inhalte"), "personal_data_check": ("bool", "Personendaten prüfen", "vor dem Senden"),
                                "show_error_notice": ("bool", "Hinweis «KI kann Fehler machen»", "im Chat")}, "pflicht": ["display_name", "retention_days"]},
        "EndpointCheck": {"title": "Prüfung", "description": "Ergebnis einer Verbindungsprüfung",
                          "felder": {"checked_at": ("datetime", "Geprüft am", "Zeitpunkt"), "is_reachable": ("bool", "Erreichbar", "Schnittstelle antwortet"),
                                     "latency_ms": ("int?", "Antwortzeit (ms)", "Messung"), "gpu_load_percent": ("int?", "GPU-Auslastung (%)", "eigene Hardware"), "message": ("text?", "Meldung", "Fehlertext")}},
        "SystemStatus": {"title": "Systemzustand", "description": "Übersicht für die Verwaltung",
                         "felder": {"checked_at": ("datetime", "Letzte Prüfung", "Zeitpunkt"), "endpoints": ("list:object", "Betriebsorte", "Name, Status, letzte Prüfung"),
                                    "chunk_count": ("int", "Suchindex", "Abschnitte"), "usage": ("list:ref:UsageRow", "Nutzung", "je Modell")}},
        "UsageRow": {"title": "Nutzung", "description": "Summe je Modell im Zeitraum (aus dem Metadaten-Protokoll)",
                     "felder": {"model_id": ("uuid", "Modell", "Verweis"), "request_count": ("int", "Anfragen", "Anzahl"), "input_tokens": ("int", "Tokens Eingabe", "Summe"),
                                "output_tokens": ("int", "Tokens Antwort", "Summe"), "helpful_count": ("int", "Hilfreich", "Daumen hoch"), "not_helpful_count": ("int", "Nicht hilfreich", "Daumen runter")}},
        "AssistantExport": {"title": "Assistent (Datei)", "description": "Austauschformat «eduksx-ai-assistant/1»; Wissen und Freigabe werden nicht übertragen",
                            "felder": {"format": ("text", "Format", "«eduksx-ai-assistant/1»"), "name": ("text", "Name", "Anzeige"), "symbol": ("text?", "Symbol", "ein bis zwei Zeichen"),
                                       "description": ("text?", "Kurzbeschreibung", "Anzeige"), "instructions": ("text?", "Anweisungen", "an das Modell"),
                                       "model_identifier": ("text?", "Modell", "Kennung"), "protection_level": (SCHUTZ, "Schutzbedarf", "Vorgabe"), "starters": ("list:text", "Gesprächsanfänge", "Vorschläge")},
                            "pflicht": ["format", "name"]},
    },
    "aktionen": [
        {"pfad": f"{M}/conversations/{{id}}/messages", "methode": "get", "op": "listMessages", "summary": "Nachrichten einer Unterhaltung", "ressource": "conversations",
         "antwort": "liste:Message", "klassen": ["personal"], "fehler": ("401", "403", "404")},
        {"pfad": f"{M}/conversations/{{id}}/messages", "op": "sendMessage", "summary": "Nachricht senden und Antwort erhalten", "ressource": "messages",
         "beschreibung": "Prüft Personendaten (409 mit PersonalDataHint), wählt den zulässigen Betriebsort nach Schutzbedarf (sonst 422) und leitet über das "
                         "Gateway an die OpenAI-kompatible Schnittstelle weiter. Mit «stream» als Ereignisstrom (text/event-stream: delta, sources, done).",
         "body": "SendMessage", "antwort": "Message", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{M}/conversations/{{id}}/messages/{{message_id}}/regeneration", "pfadparam": {"message_id": ("Nachricht", "ID der Antwort (UUID)", "0193a1b2-0000-7000-8000-000000000001")}, "op": "regenerateMessage", "summary": "Antwort neu erzeugen", "ressource": "messages",
         "antwort": "Message", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{M}/conversations/{{id}}/messages/{{message_id}}/feedback", "methode": "put", "pfadparam": {"message_id": ("Nachricht", "ID der Antwort (UUID)", "0193a1b2-0000-7000-8000-000000000001")}, "op": "rateMessage", "summary": "Antwort bewerten", "ressource": "messages",
         "body": "Feedback", "antwort": "Message", "klassen": ["personal"]},
        {"pfad": f"{M}/conversations/{{id}}/attachments", "op": "uploadAttachment", "summary": "Datei anhängen", "ressource": "messages", "beschreibung": "Virenprüfung; Inhalt bleibt im Objektspeicher (Schweiz).",
         "body": "datei", "antwort": "Attachment", "code": "201", "klassen": ["personal"]},
        {"pfad": f"{M}/conversations/{{id}}/stop", "op": "stopGeneration", "summary": "Laufende Antwort abbrechen", "ressource": "messages", "antwort": None, "code": "204", "klassen": ["personal"]},
        {"pfad": f"{O}/assistants/{{id}}/favorite", "methode": "put", "op": "setAssistantFavorite", "summary": "Als Favorit markieren", "ressource": "assistants", "recht": "read", "antwort": None, "code": "204"},
        {"pfad": f"{O}/assistants/{{id}}/export", "methode": "get", "op": "exportAssistant", "summary": "Als Datei exportieren", "ressource": "assistants", "recht": "read", "antwort": "AssistantExport"},
        {"pfad": f"{O}/assistants/import", "op": "importAssistant", "summary": "Aus Datei übernehmen", "ressource": "assistants", "body": "AssistantExport", "antwort": "Assistant", "code": "201"},
        {"pfad": f"{O}/knowledge-collections/{{id}}/files", "methode": "get", "op": "listKnowledgeFiles", "summary": "Dateien einer Sammlung", "ressource": "knowledge", "recht": "read",
         "antwort": "liste:KnowledgeFile", "fehler": ("401", "403", "404")},
        {"pfad": f"{O}/knowledge-collections/{{id}}/files", "op": "uploadKnowledgeFile", "summary": "Datei hinzufügen und indexieren", "ressource": "knowledge",
         "beschreibung": "Indexierung läuft im Hintergrund auf dem internen Server (Status «indexing» → «indexed»).", "body": "datei", "antwort": "KnowledgeFile", "code": "202"},
        {"pfad": f"{O}/knowledge-collections/{{id}}/files/{{file_id}}", "methode": "delete", "pfadparam": {"file_id": ("Datei", "ID der Datei (UUID)", "0193a1b2-0000-7000-8000-000000000002")}, "op": "deleteKnowledgeFile", "summary": "Datei und ihre Abschnitte entfernen", "ressource": "knowledge",
         "antwort": None, "code": "204"},
        {"pfad": f"{O}/default-models", "methode": "get", "op": "getDefaultModels", "summary": "Standardmodell je Schutzbedarf", "ressource": "models", "recht": "read", "antwort": "DefaultModels"},
        {"pfad": f"{O}/default-models", "methode": "put", "op": "saveDefaultModels", "summary": "Standardmodelle speichern", "ressource": "models", "recht": "admin",
         "beschreibung": "Jedes Modell muss für seine Stufe einen zulässigen Betriebsort haben (sonst 422).", "body": "DefaultModels", "antwort": "DefaultModels"},
        {"pfad": f"{O}/endpoints/{{id}}/check", "op": "checkEndpoint", "summary": "Verbindung testen", "ressource": "endpoints", "recht": "admin", "antwort": "EndpointCheck"},
        {"pfad": f"{O}/settings", "methode": "get", "op": "getSettings", "summary": "Organisation und Datenschutzregeln", "ressource": "settings", "recht": "read", "antwort": "Settings"},
        {"pfad": f"{O}/settings", "methode": "put", "op": "saveSettings", "summary": "Einstellungen speichern", "ressource": "settings", "recht": "admin", "body": "Settings", "antwort": "Settings", "ifmatch": True},
        {"pfad": f"{O}/system-status", "methode": "get", "op": "getSystemStatus", "summary": "Systemzustand und Nutzung", "ressource": "status", "recht": "admin",
         "query": [("valid_from", "date", "Von", "Zeitraum Nutzung"), ("valid_until", "date", "Bis", "Zeitraum Nutzung")], "antwort": "SystemStatus"},
        {"pfad": f"{O}/system-status/check", "op": "runSystemCheck", "summary": "Jetzt prüfen", "ressource": "status", "recht": "admin", "antwort": "SystemStatus", "code": "202"},
        {"pfad": f"{O}/user-accounts/sync", "op": "syncUserAccounts", "summary": "Mit EduKSX-Ident abgleichen", "ressource": "groups", "recht": "admin", "antwort": None, "code": "202"},
    ],
}
